import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Guide: readers — reading a reply in code","description":"","frontmatter":{},"headers":[],"relativePath":"build/readers.md","filePath":"build/readers.md"}`),a={name:`build/readers.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="guide-readers-—-reading-a-reply-in-code" tabindex="-1">Guide: readers — reading a reply in code <a class="header-anchor" href="#guide-readers-—-reading-a-reply-in-code" aria-label="Permalink to “Guide: readers — reading a reply in code”">​</a></h1><p><code>@marg-adk/core</code> exports the readers the runtime uses; use the same ones in your steps and your eval checks so the rule never drifts.</p><table tabindex="0"><thead><tr><th>Reader</th><th>Reads</th><th>Returns</th></tr></thead><tbody><tr><td><code>readYesNo(text, extraYes?, {strict})</code></td><td>a plain yes / no / skip by the whole message</td><td><code>&quot;yes&quot; | &quot;no&quot; | &quot;skip&quot; | &quot;words&quot;</code></td></tr><tr><td><code>isPlainYes</code>, <code>isPlainNo</code>, <code>isPlainSkip</code>, <code>isQuestionShaped</code></td><td>the primitives behind it</td><td>boolean</td></tr><tr><td><code>isCreateYes(text)</code></td><td>the create gate&#39;s stricter reading (soft acknowledgements never count)</td><td>boolean</td></tr><tr><td><code>readChoice(text, options, {picking})</code></td><td>an option&#39;s value or label, or distinctive words of exactly one option</td><td><code>pick | none | words</code></td></tr><tr><td><code>readNumber(text)</code></td><td>a lone number (with a unit word)</td><td>number or undefined</td></tr><tr><td><code>readAmount(text, {units})</code></td><td>the first money-like figure with a magnitude word and a basis</td><td><code>{amount, unit, basis, raw}</code></td></tr><tr><td><code>parseFormReply(text, rows)</code>, <code>looksLikeFormReply</code></td><td>the form wire format <code>Label [key]: value; …</code></td><td><code>{key: value}</code></td></tr><tr><td><code>readEdit(text, sections, picking)</code></td><td>the review picker: a section, the menu, none, other, words</td><td><code>EditRead</code></td></tr><tr><td><code>allWordsIn(text, allowed)</code></td><td>the generic &quot;every word accounted for&quot; check</td><td>boolean</td></tr></tbody></table><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to “The rule”">​</a></h2><p>A reply is a plain X only when EVERY word is an X word, politeness, filler, or a noun of the question. Anything else is content → <code>words</code> → the model answers and the runtime redraws its ask. The cost is asymmetric: a false <code>words</code> costs one repeated tap; a false yes settles a value or performs a write.</p><h2 id="extending-the-vocabulary" tabindex="-1">Extending the vocabulary <a class="header-anchor" href="#extending-the-vocabulary" aria-label="Permalink to “Extending the vocabulary”">​</a></h2><p><code>extendLexicon({ confirm: [...], refuse: [...], neutral: [...] })</code> adds your users&#39; register. Add only words that cannot carry content on their own — every widening is a hole at the gate. Measure on a blind corpus: have someone write 100 realistic messages that are NOT a bare yes (instructions, facts, questions, corrections) and count how many the reader swallows. The shipped lexicon swallowed 0 of 267.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/guides/readers.md">docs/guides/readers.md</a> — edit it there; the site mirrors the repository.</small></p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};